/**
 * @param {string} ticker  NSE ticker, e.g. 'MOTHERSON'
 * @returns {{ prowessName: string } | null}
 */
function resolveProwess(ticker) {
  const name = TICKER_MAP[ticker];
  if (!name) return null;
  return { prowessName: name };
}

module.exports = { resolveProwess };
